import {createClient} from '@/lib/supabase/server'
import {redirect} from 'next/navigation'
import {createVendor} from './actions'
export default async function Vendors({searchParams}:{searchParams:Promise<{error?:string;success?:string}>}){const q=await searchParams;const s=await createClient();const {data:c}=await s.auth.getClaims();const uid=c?.claims?.sub as string|undefined;if(!uid)redirect('/login');const {data:p}=await s.from('profiles').select('role').eq('id',uid).maybeSingle();if(!['admin','procurement','vendor_manager'].includes(p?.role||''))redirect('/investor');const {data:rows}=await s.from('vendors').select('*').order('created_at',{ascending:false});return <div className="dashboard"><div className="container"><h1>Suplidores y contratistas</h1><p className="muted">Registro y control básico de proveedores del proyecto.</p>{q.error&&<div className="card">Error: {q.error}</div>}{q.success&&<div className="card">Suplidor creado.</div>}<section className="card" style={{margin:'16px 0'}}><h2>Nuevo suplidor</h2><form action={createVendor} className="form-grid"><label>Razón social<input name="legal_name" required/></label><label>Nombre comercial<input name="trade_name"/></label><label>Tipo<select name="vendor_type"><option>contractor</option><option>supplier</option><option>consultant</option><option>service_provider</option></select></label><label>RNC / Tax ID<input name="tax_id"/></label><label>País<input name="country"/></label><label>Contacto<input name="contact_name"/></label><label>Email<input name="email" type="email"/></label><label>Teléfono<input name="phone"/></label><div style={{gridColumn:'1/-1'}}><button className="button">Registrar suplidor</button></div></form></section><section className="card" style={{overflowX:'auto'}}><table style={{width:'100%',borderCollapse:'collapse'}}><thead><tr><th style={{padding:10,textAlign:'left'}}>Razón social</th><th style={{padding:10,textAlign:'left'}}>Tipo</th><th style={{padding:10,textAlign:'left'}}>KYC</th><th style={{padding:10,textAlign:'left'}}>Estado</th></tr></thead><tbody>{(rows||[]).map(v=><tr key={v.id} style={{borderTop:'1px solid #e5e7eb'}}><td style={{padding:10}}>{v.legal_name}</td><td style={{padding:10}}>{v.vendor_type}</td><td style={{padding:10}}>{v.kyc_status}</td><td style={{padding:10}}>{v.status}</td></tr>)}</tbody></table></section></div></div>}
